(function () {
    var now = new Date();
    // Mặc định: đầu năm → hôm nay (khớp khoảng tuyển sinh thường dùng)
    var firstDay = new Date(now.getFullYear(), 0, 1);
    var fmt = function (d) {
        var m = d.getMonth() + 1;
        var day = d.getDate();
        return d.getFullYear()
            + '-' + (m < 10 ? '0' : '') + m
            + '-' + (day < 10 ? '0' : '') + day;
    };
    var fromEl = document.getElementById("sadDashFromDate");
    var toEl = document.getElementById("sadDashToDate");
    if (fromEl) fromEl.value = fmt(firstDay);
    if (toEl) toEl.value = fmt(now);
})();

